    void repChoices(LinearLayout parent,EditText input,String exercise,double kg){label(parent,exercise+Lang.t(" · быстрый выбор"));LinearLayout row=new LinearLayout(this);for(int n=5;n<=8;n++){final int reps=n;TextView choice=title(String.valueOf(n),18);choice.setGravity(Gravity.CENTER);choice.setBackground(shape(LINE,12));clickable(choice,()->input.setText(String.valueOf(reps)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);if(n>5)lp.leftMargin=dp(8);row.addView(choice,lp);}parent.addView(row);TextView preview=text("",14,GREEN);preview.setPadding(0,dp(10),0,dp(18));parent.addView(preview);Runnable update=()->{try{int reps=Integer.parseInt(input.getText().toString());preview.setText(Lang.t("Дальше: ")+Engine.number(kg)+" → "+Engine.number(Math.min(2000,kg+Zlat.increment(reps)))+Lang.t(" кг"));for(int i=0;i<row.getChildCount();i++){TextView t=(TextView)row.getChildAt(i);boolean selected=reps==i+5;t.setTextColor(selected?BG:TEXT);t.setBackground(shape(selected?GREEN:LINE,12));}}catch(NumberFormatException e){preview.setText(Lang.t("Введи фактические повторы выше"));}};input.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){update.run();}public void afterTextChanged(android.text.Editable e){}});update.run();}
