        scroll.post(()->scroll.fullScroll(View.FOCUS_RIGHT));space(calendar,12);LinearLayout legend=new LinearLayout(this);legend.setGravity(Gravity.CENTER_VERTICAL);legend.addView(text(Lang.t("Меньше  "),12,MUTED));for(int color:colors){View dot=new View(this);dot.setBackground(shape(color,3));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(12),dp(12));lp.rightMargin=dp(4);legend.addView(dot,lp);}legend.addView(text(Lang.t("  Больше подходов"),12,MUTED));calendar.addView(legend);calendar.addView(detail);show.accept(today);
