        LinearLayout totals=card(body);label(totals,Lang.t("ЗА ВСЁ ВРЕМЯ"));LinearLayout row=new LinearLayout(this);stat(row,String.valueOf(data.sessions),Lang.t("тренировок"),TEXT);stat(row,String.valueOf(data.sets),Lang.t("подходов"),GREEN);totals.addView(row);hint(totals,Lang.t("Как считаем активность"),Lang.t("Клетка — день сохранения занятия по времени телефона. Яркость зависит от выполненных подходов: 1–5, 6–10, 11–20, 21 и больше. Серия недель продолжается, если на прошлой неделе была тренировка: текущую неделю ещё можно заполнить. Незавершённые занятия не учитываются."));
