    void start(JSONObject p){if(Zlat.is(p)&&!p.optBoolean("configured")){zlatSetup(p,()->start(p));return;}try{store.start(p);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},1);page="workout";Notices.update(this);render();}catch(Exception e){error(e);}}
    void startWalk(){
        if(!WalkService.permitted(this)){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},94);return;}
        android.location.LocationManager manager=getSystemService(android.location.LocationManager.class);
        if(manager==null||!manager.isProviderEnabled(android.location.LocationManager.GPS_PROVIDER)){new AlertDialog.Builder(this).setMessage(Lang.t("Включи геолокацию телефона, затем начни прогулку.")).setPositiveButton(Lang.t("Открыть настройки"),(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_LOCATION_SOURCE_SETTINGS))).setNegativeButton(Lang.t("Отмена"),null).show();return;}
        try{startForegroundService(new Intent(this,WalkService.class).setAction("start"));if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},83);}catch(Exception e){error(e);}
    }
    void enableSteps(){
        if(!Steps.available(this))return;
        if(!Steps.permitted(this)){
            if(Steps.prefs(this).getBoolean("asked",false)&&!shouldShowRequestPermissionRationale(Manifest.permission.ACTIVITY_RECOGNITION)){
                new AlertDialog.Builder(this).setMessage(Lang.t("Разреши физическую активность для подсчёта шагов в настройках Trace.")).setPositiveButton(Lang.t("Открыть настройки"),(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())))).setNegativeButton(Lang.t("Отмена"),null).show();return;
            }
            if(Build.VERSION.SDK_INT>=29){Steps.prefs(this).edit().putBoolean("asked",true).apply();requestPermissions(new String[]{Manifest.permission.ACTIVITY_RECOGNITION},82);}return;
        }
        try{Steps.enable(this);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},83);stepHandler.postDelayed(()->{if(!isFinishing()&&page.equals("steps"))render();},500);render();}catch(RuntimeException e){error(e);}
    }
    @Override public void onRequestPermissionsResult(int r,String[] ps,int[] result){super.onRequestPermissionsResult(r,ps,result);if(r==94){if(WalkService.permitted(this))startWalk();else new AlertDialog.Builder(this).setMessage(Lang.t("Для маршрута разреши точную геолокацию. Шагомер работает и без неё.")).setPositiveButton(Lang.t("Открыть настройки"),(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())))).setNegativeButton(Lang.t("Отмена"),null).show();}if(r==82){if(Steps.permitted(this))enableSteps();else Toast.makeText(this,Lang.t("Нужно разрешение на физическую активность"),Toast.LENGTH_LONG).show();}Notices.update(this);render();}
