    double positive(EditText e,boolean zero){double n=Double.parseDouble(e.getText().toString().trim().replace(',','.'));if(!Double.isFinite(n)||n<(zero?0:0.01)||n>2000)throw new IllegalArgumentException(Lang.t("Введите число ")+(zero?Lang.t("от 0"):Lang.t("больше 0"))+Lang.t(" до 2000"));return n;}
    int integer(EditText e,int max){double n=positive(e,false);if(n!=Math.rint(n)||n>max)throw new IllegalArgumentException(Lang.t("Нужно целое число от 1 до ")+max);return (int)n;}
    void editSet(int index){JSONObject session=store.active();if(session==null)return;String sessionId=session.optString("id");JSONArray sets=session.optJSONArray("sets");JSONObject set=sets.optJSONObject(index);LinearLayout box=form();EditText kg=input(box,Lang.t("Рабочий вес, кг · 0 = без отягощения"),set.optDouble("kg",-1)<0?"":Engine.number(set.optDouble("kg")),true);EditText reps=input(box,Lang.t("Повторения"),String.valueOf(set.optInt("reps")),true);CheckBox all=new CheckBox(this);all.setText(Lang.t("Остальные подходы этого блока"));all.setTextColor(TEXT);box.addView(all);
        formDialog(set.optString("exercise"),box,Lang.t("Сохранить"),()->{double w=positive(kg,true);int r=integer(reps,1000);JSONObject active=store.active();if(active==null||!active.optString("id").equals(sessionId))throw new IllegalArgumentException(Lang.t("Этот подход уже выполнен"));for(int n=index;n<sets.length();n++){JSONObject x=sets.optJSONObject(n);if(n==index||(all.isChecked()&&!x.optBoolean("done")&&x.optInt("group")==set.optInt("group"))){Engine.put(x,"kg",w);Engine.put(x,"reps",r);JSONObject plan=store.program(active.optString("programId"));if(x.has("factor")&&plan!=null)Engine.put(x,"manualWeight",Math.abs(w-Engine.weight(x,plan.optJSONObject("maxima"),plan.optDouble("step",2.5)))>.00001);}}Engine.put(active,"revision",active.optInt("revision")+1);store.save();Notices.update(this);render();});}

    void maxima(JSONObject p){if(Zlat.is(p)){zlatSetup(p,()->{});return;}
        LinearLayout box=form();box.addView(text(Lang.t("Введи максимумы, от которых строится план. Все процентные веса обновятся сразу — во всех днях и в оставшихся подходах текущего занятия."),15,MUTED));space(box,18);JSONObject max=p.optJSONObject("maxima");String[] names={Lang.t("Присед · 100%, кг"),Lang.t("Жим лёжа · 100%, кг"),Lang.t("Становая тяга · 100%, кг")};ArrayList<EditText> inputs=new ArrayList<>();ArrayList<String> keys=new ArrayList<>();
        for(int i=0;i<3;i++)if(max.has(Importer.LIFTS[i])){keys.add(Importer.LIFTS[i]);inputs.add(input(box,names[i],Engine.number(max.optDouble(Importer.LIFTS[i])),true));}
        box.addView(text(Lang.t("Выполненные подходы и вручную выбранные веса сохранятся."),13,MUTED));
        formDialog(Lang.t("Максимумы на всю программу"),box,Lang.t("Применить ко всем дням"),()->{JSONObject changed=Engine.copy(max);for(int i=0;i<keys.size();i++)Engine.put(changed,keys.get(i),positive(inputs.get(i),false));store.updateMaxima(p,changed,0);Notices.update(this);render();Toast.makeText(this,Lang.t("Веса программы обновлены"),Toast.LENGTH_SHORT).show();});
    }

    AlertDialog dayPanel;
    void dayDialog(JSONObject p,int d){JSONObject day=p.optJSONArray("days").optJSONObject(d);LinearLayout box=form();if(!day.optString("note").isEmpty()){box.addView(text(day.optString("note"),15,GREEN));space(box,12);}box.addView(text(Lang.t("Рабочие веса уже рассчитаны от твоих максимумов. Чтобы изменить вес сразу во всех днях, открой «Твои максимумы» в программе."),13,MUTED));JSONArray groups=day.optJSONArray("groups");for(int i=0;i<groups.length();i++){final int gi=i;final JSONObject g=groups.optJSONObject(i);LinearLayout c=card(box);c.addView(title(g.optString("exercise"),17));double w=Engine.weight(g,p.optJSONObject("maxima"),2.5);c.addView(text((w<0?Lang.t("Вес выбирается в зале"):Engine.number(w)+Lang.t(" кг"))+" · "+g.optInt("sets")+" × "+g.optInt("reps"),14,MUTED));link(c,Lang.t("Изменить"),()->editGroup(p,g));if(groups.length()>1)link(c,Lang.t("Удалить упражнение"),()->{DeletedItems.exercise(store.data,p,d,gi);store.save();if(dayPanel!=null)dayPanel.dismiss();render();});}button(box,Lang.t("＋ Добавить упражнение"),false,()->addGroup(p,day));dayPanel=panel(day.optString("name"),box,Lang.t("Закрыть"),()->{},false);}
    void editGroup(JSONObject p,JSONObject g){LinearLayout box=form();EditText exercise=input(box,Lang.t("Упражнение"),g.optString("exercise"),false);double w=Engine.weight(g,p.optJSONObject("maxima"),2.5);EditText kg=input(box,Lang.t("Фиксированный вес, кг (пусто = выбрать в зале)"),w<0?"":Engine.number(w),true);EditText sets=input(box,Lang.t("Подходы"),String.valueOf(g.optInt("sets")),true),reps=input(box,Lang.t("Повторения"),String.valueOf(g.optInt("reps")),true);CheckBox preserve=new CheckBox(this);preserve.setText(Lang.t("Сохранить расчёт от максимума"));preserve.setTextColor(TEXT);preserve.setChecked(g.has("factor"));if(g.has("factor")){box.addView(preserve);kg.setEnabled(false);preserve.setOnCheckedChangeListener((b,checked)->kg.setEnabled(!checked));}
        formDialog(Lang.t("Редактировать блок"),box,Lang.t("Сохранить"),()->{String name=exercise.getText().toString().trim();if(name.isEmpty())throw new IllegalArgumentException(Lang.t("Укажи название"));int sn=integer(sets,100),rn=integer(reps,1000);double weight=kg.getText().toString().trim().isEmpty()?-1:positive(kg,true);Engine.put(g,"exercise",name);Engine.put(g,"sets",sn);Engine.put(g,"reps",rn);if(!preserve.isChecked()){g.remove("factor");g.remove("lift");Engine.put(g,"kg",weight);}store.save();render();});}
    void history(){
        badge(body,Lang.t("ЖУРНАЛ РЕЗУЛЬТАТОВ"),0xFFE6C58A);space(body,14);heading(Lang.t("Твой прогресс"),Lang.t("Прошлые занятия, веса и повторения."));JSONArray h=store.data.optJSONArray("history");
        if(h.length()==0){LinearLayout c=card(body);coverBackground(c,R.drawable.strength_cover);largeIcon(c,"history",0xFFE6C58A);space(c,20);c.addView(title(Lang.t("Прогресс начинается здесь"),24));space(c,10);c.addView(text(Lang.t("Заверши первое занятие — результат появится здесь."),16,MUTED));button(c,Lang.t("К тренировке"),true,()->{page="workout";render();});return;}
        int count=0;for(int i=0;i<h.length();i++)count+=Engine.doneCount(h.optJSONObject(i));LinearLayout stats=card(body);stats.setBackground(shape(0xFF302A20,16));badge(stats,Lang.t("ИТОГО ЗА ВСЁ ВРЕМЯ"),0xFFE6C58A);space(stats,12);LinearLayout values=new LinearLayout(this);stat(values,String.valueOf(h.length()),Lang.t("тренировок"),TEXT);stat(values,String.valueOf(count),Lang.t("подходов"),GREEN);stats.addView(values);
        String month="";for(int i=h.length()-1;i>=0;i--){JSONObject session=h.optJSONObject(i);Date date=new Date(session.optLong("ended"));String m=new SimpleDateFormat("LLLL yyyy",Lang.locale()).format(date);if(!m.equals(month)){space(body,12);label(body,m.toUpperCase(Lang.locale()));month=m;}LinearLayout c=card(body);GradientDrawable paper=shape(0xFF28251F,12);paper.setStroke(dp(1),0xFF514735);c.setBackground(paper);badge(c,new SimpleDateFormat("d MMM · HH:mm",Lang.locale()).format(date),BLUE);space(c,14);c.addView(title(session.optString("dayName"),22));space(c,6);c.addView(text(session.optString("programName"),14,MUTED));space(c,16);c.addView(text("✓  "+Engine.doneCount(session)+Lang.t(" подходов выполнено"),14,GREEN));actionRow(c,"arrow",Lang.t("Посмотреть результат"),Lang.t("Упражнения, веса и повторения"),()->historyDetail(session));}
    }
    void historyDetail(JSONObject session){LinearLayout box=form();badge(box,Lang.t("ТРЕНИРОВКА СОХРАНЕНА"),GREEN);space(box,12);box.addView(text(session.optString("programName"),14,MUTED));space(box,20);JSONArray sets=session.optJSONArray("sets");String previous="";LinearLayout c=null;for(int i=0;i<sets.length();i++){JSONObject set=sets.optJSONObject(i);String name=Lang.content(set.optString("exercise"));if(!name.equals(previous)){c=card(box);c.addView(title(name,18));space(c,12);previous=name;}LinearLayout row=new LinearLayout(this);row.setPadding(0,dp(9),0,dp(9));TextView mark=text(set.optBoolean("done")?"✓":"—",16,GREEN);row.addView(mark,new LinearLayout.LayoutParams(dp(28),-2));double kg=set.optDouble("kg",-1);TextView result=text((kg<0?Lang.t("Без веса"):Engine.number(kg)+Lang.t(" кг"))+" × "+set.optInt("reps"),16,TEXT);row.addView(result,new LinearLayout.LayoutParams(0,-2,1));row.addView(text("#"+(i+1),13,MUTED));c.addView(row);}panel(Lang.content(session.optString("dayName")),box,Lang.t("Готово"),()->{},false);}
    
    static final String TEMPLATE="день;упражнение;подходы;повторения;вес\nДень 1;Присед;3;5;60\nДень 1;Жим лёжа;3;5;40\nДень 2;Становая тяга;3;5;80\n";
    void editor(JSONObject ignored){LinearLayout box=form();EditText name=input(box,Lang.t("Название программы"),Lang.t("Моя программа"),false);formDialog(Lang.t("Своя программа"),box,Lang.t("Добавить первый день"),()->{String title=name.getText().toString().trim();if(title.isEmpty())throw new IllegalArgumentException(Lang.t("Введи название программы"));JSONObject p=Importer.newProgram(title);addDay(p);});}
    void addDay(JSONObject p){LinearLayout box=form();EditText day=input(box,Lang.t("Название дня"),Lang.t("День ")+(p.optJSONArray("days").length()+1),false);EditText exercise=input(box,Lang.t("Первое упражнение"),"",false);EditText sets=input(box,Lang.t("Подходы"),"3",true);EditText reps=input(box,Lang.t("Повторения"),"5",true);EditText kg=input(box,Lang.t("Вес, кг · пусто = выбрать в зале"),"",true);formDialog(Lang.t("Новый тренировочный день"),box,Lang.t("Добавить"),()->{String dn=day.getText().toString().trim(),en=exercise.getText().toString().trim();if(dn.isEmpty()||en.isEmpty())throw new IllegalArgumentException(Lang.t("Введи название дня и упражнения"));JSONObject g=new JSONObject();Engine.put(g,"exercise",en);Engine.put(g,"sets",integer(sets,100));Engine.put(g,"reps",integer(reps,1000));Engine.put(g,"kg",kg.getText().toString().trim().isEmpty()?-1:positive(kg,true));JSONObject d=Engine.obj("{\"groups\":[]}");Engine.put(d,"name",dn);d.optJSONArray("groups").put(g);p.optJSONArray("days").put(d);if(!p.has("id")){Engine.put(p,"id",Engine.id());Engine.put(p,"mine",true);Engine.put(p,"lastUsed",System.currentTimeMillis());store.data.optJSONArray("programs").put(p);}store.save();open(p);});}
    void pick(int code){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,code);}
    void addGroup(JSONObject p,JSONObject day){LinearLayout box=form();EditText name=input(box,Lang.t("Упражнение"),"",false),sets=input(box,Lang.t("Подходы"),"3",true),reps=input(box,Lang.t("Повторения"),"5",true),kg=input(box,Lang.t("Вес, кг · пусто = выбрать в зале"),"",true);formDialog(Lang.t("Добавить упражнение"),box,Lang.t("Добавить"),()->{String n=name.getText().toString().trim();if(n.isEmpty())throw new IllegalArgumentException(Lang.t("Введи название упражнения"));JSONObject g=new JSONObject();Engine.put(g,"exercise",n);Engine.put(g,"sets",integer(sets,100));Engine.put(g,"reps",integer(reps,1000));Engine.put(g,"kg",kg.getText().toString().trim().isEmpty()?-1:positive(kg,true));day.optJSONArray("groups").put(g);store.save();render();});}
    AlertDialog importPreview;
    void preview(JSONObject p){LinearLayout box=form();EditText name=input(box,Lang.t("Название"),p.optString("name"),false);int sets=0,missing=0;StringBuilder summary=new StringBuilder();JSONArray days=p.optJSONArray("days");for(int i=0;i<days.length();i++){JSONObject d=days.optJSONObject(i);summary.append(d.optString("name")).append("\n").append(daySummary(d)).append("\n\n");JSONArray groups=d.optJSONArray("groups");for(int g=0;g<groups.length();g++){sets+=groups.optJSONObject(g).optInt("sets");if(groups.optJSONObject(g).optDouble("kg",-1)<0)missing++;}}
        box.addView(title(days.length()+Lang.t(" дней · ")+sets+Lang.t(" подходов"),19));space(box,10);if(missing>0)box.addView(text(Lang.t("В ")+missing+Lang.t(" блоках вес не указан: выберешь его перед подходом."),14,GREEN));space(box,12);for(int di=0;di<days.length();di++){JSONObject day=days.optJSONObject(di);LinearLayout c=card(box);badge(c,Lang.t("ДЕНЬ ")+(di+1),BLUE);space(c,12);c.addView(title(day.optString("name"),18));space(c,8);c.addView(text(daySummary(day),14,MUTED));}importPreview=formDialog(Lang.t("Проверка импорта"),box,Lang.t("Добавить в мои"),()->{Engine.put(p,"name",name.getText().toString().trim());Engine.validateProgram(p);Engine.put(p,"id",Engine.id());Engine.put(p,"mine",true);Engine.put(p,"nextDay",0);Engine.put(p,"lastUsed",System.currentTimeMillis());store.data.optJSONArray("programs").put(p);store.save();open(p);});}
    void export(String name,String content){exportText=content;if(!rememberExport())return;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(name.endsWith("csv")?"text/csv":"application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,name),41);}
    void settings(){
        heading(Lang.t("Настройки"),Lang.t("Твои данные. Твои правила."));
        LinearLayout intro=card(body);photoBackground(intro,1);largeIcon(intro,"trace",GREEN);space(intro,16);intro.addView(title("Trace",28));space(intro,6);intro.addView(text(Lang.t("Твой дневник силы"),15,MUTED));space(intro,14);badge(intro,Lang.t("НА ТЕЛЕФОНЕ · БЕЗ АККАУНТА"),GREEN);
        LinearLayout languageCard=card(body);label(languageCard,Lang.t("Язык приложения"));LinearLayout choices=new LinearLayout(this);languageCard.addView(choices);String[] codes={"ru","en"},labels={"Русский","English"};for(int i=0;i<codes.length;i++){final String code=codes[i];boolean chosen=Lang.english()==code.equals("en");TextView choice=title((chosen?"✓  ":"")+labels[i],16);choice.setGravity(Gravity.CENTER);choice.setTextColor(chosen?BG:TEXT);choice.setBackground(shape(chosen?GREEN:LINE,14));clickable(choice,()->{if(Lang.english()==code.equals("en"))return;Lang.set(this,code);Notices.update(this);recreate();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(54),1);if(i>0)lp.leftMargin=dp(10);choices.addView(choice,lp);}
        label(body,Lang.t("ДАННЫЕ И РЕЗЕРВНЫЕ КОПИИ"));LinearLayout backup=card(body);actionRow(backup,"export",Lang.t("Сохранить копию"),Lang.t("Планы, обложки, история, шаги и настройки"),()->backup());long last=getSharedPreferences("trace-settings",0).getLong("lastBackupAt",0);backup.addView(text(last==0?Lang.t("Копия ещё не сохранялась"):Lang.t("Последняя копия: ")+new SimpleDateFormat("d MMM yyyy · HH:mm",Lang.locale()).format(new Date(last)),13,MUTED));divider(backup);actionRow(backup,"file",Lang.t("Восстановить из файла"),Lang.t("Загрузить ранее сохранённую копию"),()->pick(42));
        label(body,Lang.t("КАК ЭТО РАБОТАЕТ"));LinearLayout tips=card(body);actionRow(tips,"library",Lang.t("Добавление программ"),Lang.t("XLS Шейко · CSV · XLSX · JSON"),()->{LinearLayout b=form();b.addView(text(Lang.t("Можно загрузить исходную XLS-таблицу Шейко, JSON программы или CSV / XLSX по шаблону. В XLSX используется первый лист с пятью колонками."),16,MUTED));panel(Lang.t("Импорт программы"),b,Lang.t("Понятно"),()->{},false);});space(body,8);TextView version=text(Lang.t("Trace  /  ВЕРСИЯ 0.20.6"),12,MUTED);version.setGravity(Gravity.CENTER);body.addView(version);space(body,12);
    }
    
    void restore(JSONObject backup){JSONObject data=FullBackup.workouts(backup);if(data.has("savedSessions")){JSONObject saved=data.optJSONObject("savedSessions");if(saved==null)throw new IllegalArgumentException(Lang.t("Повреждены сохранённые занятия"));Iterator<String> sessions=saved.keys();while(sessions.hasNext()){String key=sessions.next();JSONObject session=saved.optJSONObject(key);validateSession(session);if(!key.equals(session.optString("programId")))throw new IllegalArgumentException(Lang.t("Повреждена связь занятия с программой"));}}JSONArray programs=data.optJSONArray("programs"),history=data.optJSONArray("history");if(programs==null||history==null)throw new IllegalArgumentException(Lang.t("Это не резервная копия Trace"));HashSet<String> ids=new HashSet<>();for(int i=0;i<programs.length();i++){JSONObject p=programs.optJSONObject(i);Engine.validateProgram(p);if(p.optString("id").isEmpty()||!ids.add(p.optString("id"))||p.optInt("nextDay")<0||p.optInt("nextDay")>p.optJSONArray("days").length())throw new IllegalArgumentException(Lang.t("Повреждена программа в копии"));}for(int i=0;i<history.length();i++)validateSession(history.optJSONObject(i));if(data.has("active")){validateSession(data.optJSONObject("active"));if(!ids.contains(data.optJSONObject("active").optString("programId")))throw new IllegalArgumentException(Lang.t("В копии отсутствует активная программа"));}new AlertDialog.Builder(this).setTitle(Lang.t("Восстановить копию?")).setMessage((backup.has("format")?Lang.t("Шаги и настройки также будут заменены. "):"")+Lang.t("Текущие данные будут заменены: ")+programs.length()+Lang.t(" программ, ")+history.length()+Lang.t(" тренировок. Сначала сохрани текущую копию, если она нужна.")).setNegativeButton(Lang.t("Отмена"),null).setPositiveButton(Lang.t("Восстановить"),(d,w)->{try{FullBackup.apply(this,store,backup,data);Notices.update(this);page="mine";recreate();}catch(Exception e){error(e);}}).show();}
    void validateSession(JSONObject s){if(s==null||s.optJSONArray("sets")==null||s.optString("id").isEmpty())throw new IllegalArgumentException(Lang.t("Повреждена тренировка в копии"));JSONArray a=s.optJSONArray("sets");if(a.length()==0||s.optInt("cursor")<0||s.optInt("cursor")>a.length())throw new IllegalArgumentException(Lang.t("Повреждён прогресс"));for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null||x.optString("exercise").isEmpty()||x.optInt("reps")<1||x.optInt("sets")<1||!Double.isFinite(x.optDouble("kg",-1))||x.optDouble("kg",-1)<-1)throw new IllegalArgumentException(Lang.t("Повреждены подходы"));}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==44){
        final String target=coverTarget;coverTarget="";
        Toast.makeText(this,Lang.t("Читаю файл…"),Toast.LENGTH_SHORT).show();
        new Thread(()->{try{String encoded=PlanImages.read(getApplicationContext(),uri);runOnUiThread(()->{
            JSONObject p=store.program(target);if(p==null)return;
            if(!isDestroyed()&&!isFinishing())CoverEditor.show(this,p,encoded,false);
        });}catch(Exception e){runOnUiThread(()->{if(!isDestroyed())error(e);});}},"trace-cover").start();return;
    }if(request==41||request==43){try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(exportText.getBytes(StandardCharsets.UTF_8));out.flush();out.close();if(request==43){getSharedPreferences("trace-settings",0).edit().putLong("lastBackupAt",System.currentTimeMillis()).commit();render();}Toast.makeText(this,Lang.t("Файл сохранён"),Toast.LENGTH_SHORT).show();}catch(Exception e){error(e);}return;}if(request!=40&&request!=42)return;
        importFile(uri,request==42);}
    void importFile(Uri uri,boolean backupFile){
        String name=Lang.t("Импортированная программа");try(android.database.Cursor c=getContentResolver().query(uri,null,null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(c.getColumnIndexOrThrow(OpenableColumns.DISPLAY_NAME));}catch(Exception ignored){}final String filename=name;Toast.makeText(this,Lang.t("Читаю файл…"),Toast.LENGTH_SHORT).show();new Thread(()->{try(InputStream in=getContentResolver().openInputStream(uri)){byte[] bytes=backupFile?FullBackup.read(in):Importer.read(in);JSONObject imported=backupFile?Engine.obj(new String(bytes,StandardCharsets.UTF_8)):Importer.parse(bytes,filename);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;try{if(backupFile)restore(imported);else preview(imported);}catch(Exception e){error(e);}});}catch(Exception e){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())error(e);});}},"import").start();}
    boolean rememberExport(){try(OutputStream out=openFileOutput("pending-export.json",0)){out.write(exportText.getBytes(StandardCharsets.UTF_8));return true;}catch(Exception e){error(e);return false;}}
    void backup(){try{exportText=FullBackup.create(this,store.data).toString();if(exportText.getBytes(StandardCharsets.UTF_8).length>FullBackup.LIMIT)throw new IllegalArgumentException(Lang.t("Копия больше 50 МБ"));if(!rememberExport())return;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"trace-backup.json"),43);}catch(Exception e){error(e);}}
    void receivePlan(Intent intent){
        String action=intent.getAction();if(!Intent.ACTION_VIEW.equals(action)&&!Intent.ACTION_SEND.equals(action))return;
        Uri uri=Intent.ACTION_VIEW.equals(action)?intent.getData():intent.getParcelableExtra(Intent.EXTRA_STREAM);
        intent.setAction(null);intent.setData(null);intent.removeExtra(Intent.EXTRA_STREAM);
        if(uri==null||!"content".equals(uri.getScheme()))return;
        importFile(uri,false);
    }
    void error(Exception e){new AlertDialog.Builder(this).setTitle(Lang.t("Не получилось")).setMessage(e.getMessage()==null?Lang.t("Проверь данные и попробуй ещё раз."):e.getMessage()).setPositiveButton(Lang.t("Понятно"),null).show();}
